const request = $json ?? {};
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};
const getHeader = (name) => { const wanted = String(name).toLowerCase(); const key = Object.keys(headers).find((item) => String(item).toLowerCase() === wanted); return key ? headers[key] : ''; };
const expected = String($env.N8N_WORKFLOWS_TOKEN || '').trim();
const provided = String(getHeader('authorization') || getHeader('x-aiops-workflows-token') || '').trim().replace(/^bearer\s+/i, '').trim();
return [{ json: { ...request, auth_ok: Boolean(expected) && provided === expected, auth_error: expected ? 'invalid workflows token' : 'N8N_WORKFLOWS_TOKEN is not configured' } }];

const payload = ($json && typeof $json === 'object' && $json.body !== undefined) ? ($json.body ?? {}) : ($json ?? {});
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const truthy = (value) => ['1', 'true', 'yes', 'y', 'on'].includes(clean(value).toLowerCase());
const imageTag = clean(payload.image_tag ?? payload.imageTag ?? payload.version);
const realm = clean(payload.realm ?? payload.tenant ?? $env.N8N_REALM ?? $env.N8N_ENV_REALM);
const dryRun = payload.dry_run === undefined && payload.dryRun === undefined ? true : truthy(payload.dry_run ?? payload.dryRun);
const allowServiceChange = truthy(payload.allow_service_change ?? payload.allowServiceChange);
const correlationId = clean(payload.correlation_id ?? payload.correlationId ?? payload.trace_id ?? payload.traceId);
if (!realm) throw new Error('realm is required');
if (!imageTag) throw new Error('image_tag is required');
if (imageTag.toLowerCase() === 'latest') throw new Error('image_tag must be an explicit version tag; latest is not allowed');
if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(imageTag)) throw new Error('image_tag contains unsupported characters');
if (!dryRun && !allowServiceChange) throw new Error('allow_service_change=true is required when dry_run=false');
return [{ json: { workflow_id: 'wf.sulu_version_deploy', service: 'sulu', realm, image_tag: imageTag, dry_run: dryRun, allow_service_change: allowServiceChange, correlation_id: correlationId || null } }];

const request = $json ?? {};
if (request.dry_run) return [{ json: { ...request, approval_evidence: null, approval_signature: null } }];
const webhook = $node['Webhook Sulu Version Deploy']?.json ?? {};
const payload = webhook.body && typeof webhook.body === 'object' ? webhook.body : webhook;
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const issueUrl = clean(payload.rfc_issue_url ?? payload.rfcIssueUrl ?? payload.change_issue_url ?? payload.changeIssueUrl);
if (!issueUrl) throw new Error('rfc_issue_url is required for a real deployment');
let parsed; try { parsed = new URL(issueUrl); } catch (error) { throw new Error('rfc_issue_url is invalid'); }
const marker = '/-/issues/'; const markerIndex = parsed.pathname.indexOf(marker);
if (markerIndex < 1) throw new Error('rfc_issue_url must be a GitLab issue URL');
const projectPath = decodeURIComponent(parsed.pathname.slice(1, markerIndex));
const issueIid = parsed.pathname.slice(markerIndex + marker.length).split('/')[0];
const gitlabApiBase = clean($env.GITLAB_API_BASE_URL || ($env.GITLAB_BASE_URL ? `${clean($env.GITLAB_BASE_URL).replace(/\/+$/, '')}/api/v4` : '')).replace(/\/+$/, '');
const gitlabToken = clean($env.N8N_GITLAB_TOKEN ?? $env.GITLAB_TOKEN);
if (!gitlabApiBase || !gitlabToken) throw new Error('GitLab API configuration is required for CAB verification');
const headers = { 'PRIVATE-TOKEN': gitlabToken };
const issue = await this.helpers.httpRequest({ method: 'GET', url: `${gitlabApiBase}/projects/${encodeURIComponent(projectPath)}/issues/${encodeURIComponent(issueIid)}`, headers, json: true, timeout: 30000 });
const notes = await this.helpers.httpRequest({ method: 'GET', url: `${gitlabApiBase}/projects/${encodeURIComponent(projectPath)}/issues/${encodeURIComponent(issueIid)}/notes`, headers, json: true, timeout: 30000, qs: { per_page: 100 } });
const labels = Array.isArray(issue?.labels) ? issue.labels.map((item) => clean(item).toLowerCase()) : [];
const approvedLabel = labels.some((label) => ['状態/approved', 'status:approved', 'cab/approved', 'approved'].includes(label));
const approvalNote = (Array.isArray(notes) ? notes : []).filter((note) => /(^|\s)\/approve(\s|$)|cab\s*approved|承認済/i.test(clean(note?.body))).sort((a, b) => Date.parse(b?.created_at || 0) - Date.parse(a?.created_at || 0))[0];
if (!approvedLabel || !approvalNote) throw new Error('GitLab RFC must have an approved label and an approval note');
const evidence = { changeId: `RFC-${issueIid}`, issueUrl: clean(issue.web_url) || issueUrl, approvedAt: clean(approvalNote.created_at), approvedBy: clean(approvalNote.author?.username ?? approvalNote.author?.name), approvalNoteId: approvalNote.id ?? null };
if (!evidence.approvedAt || !evidence.approvedBy) throw new Error('GitLab approval evidence is incomplete');
const canonical = ['deploy', request.realm, request.image_tag, evidence.changeId, evidence.issueUrl, evidence.approvedAt, evidence.approvedBy].join('\n');
const crypto = require('crypto');
const signature = crypto.createHmac('sha256', clean($env.N8N_WORKFLOWS_TOKEN)).update(canonical).digest('hex');
return [{ json: { ...request, approval_evidence: evidence, approval_signature: signature } }];

const request = $json ?? {};
const baseUrl = String($env.SERVICE_CONTROL_API_BASE_URL || '').replace(/\/+$/, '');
if (!baseUrl) throw new Error('SERVICE_CONTROL_API_BASE_URL is required');
const response = await this.helpers.httpRequest({ method: 'POST', url: `${baseUrl}/deploy`, qs: { service: 'sulu', realm: request.realm }, json: true, headers: { Authorization: `Bearer ${String($env.N8N_WORKFLOWS_TOKEN || '').trim()}` }, body: { imageTag: request.image_tag, dryRun: request.dry_run, allowServiceChange: request.allow_service_change, approvalEvidence: request.approval_evidence, approvalSignature: request.approval_signature }, timeout: 30000 });
if (!response || response.imageTag !== request.image_tag || response.dryRun !== request.dry_run) throw new Error(`Service Control deploy response is invalid: ${JSON.stringify(response)}`);
return [{ json: { ...request, service_control_response: response } }];

const request = $json ?? {};
const deploy = request.service_control_response ?? {};
if (request.dry_run) {
  const images = Array.isArray(deploy.plannedImages) ? deploy.plannedImages : [];
  const phpPlanned = images.some((item) => String(item.container || '').startsWith('php-fpm-') && String(item.to || '').endsWith(`:${request.image_tag}`));
  const nginxPlanned = images.some((item) => String(item.container || '').startsWith('nginx-') && String(item.to || '').endsWith(`:${request.image_tag}`));
  if (deploy.status !== 'validated' || deploy.applied !== false || !phpPlanned || !nginxPlanned) throw new Error(`Dry-run assertions failed: ${JSON.stringify(deploy)}`);
  return [{ json: { ok: true, workflow_id: request.workflow_id, status: 'validated', service: 'sulu', realm: request.realm, image_tag: request.image_tag, dry_run: true, applied: false, verification: { status: 'passed', mode: 'dry-run', php_image_planned: true, nginx_image_planned: true }, service_control_response: deploy, correlation_id: request.correlation_id } }];
}
const baseUrl = String($env.SERVICE_CONTROL_API_BASE_URL || '').replace(/\/+$/, '');
let status = null;
for (let attempt = 1; attempt <= 60; attempt += 1) {
  status = await this.helpers.httpRequest({ method: 'GET', url: `${baseUrl}/status`, qs: { service: 'sulu', realm: request.realm }, json: true, timeout: 30000, headers: { Authorization: `Bearer ${String($env.N8N_WORKFLOWS_TOKEN || '').trim()}` } });
  const primary = (Array.isArray(status?.deployments) ? status.deployments : []).find((item) => item?.status === 'PRIMARY');
  const desired = Number(status?.desiredCount ?? 0);
  const running = Number(status?.runningCount ?? 0);
  const health = status?.targetGroupHealth?.summary ?? {};
  const rolloutComplete = primary?.rolloutState === 'COMPLETED';
  const imageMatches = status?.imageTag === request.image_tag;
  const countsReady = desired >= 1 && running >= desired;
  const targetsReady = Number(health.unhealthy ?? 0) === 0 && Number(health.healthy ?? 0) >= 1;
  if (rolloutComplete && imageMatches && countsReady && targetsReady) {
    return [{ json: { ok: true, workflow_id: request.workflow_id, status: 'applied', service: 'sulu', realm: request.realm, image_tag: request.image_tag, dry_run: false, applied: true, task_definition: deploy.newTaskDefinition, verification: { status: 'passed', mode: 'ecs-rollout', attempts: attempt, desired_count: desired, running_count: running, healthy_targets: Number(health.healthy ?? 0) }, service_control_response: deploy, final_service_status: status, correlation_id: request.correlation_id } }];
  }
  if (primary?.rolloutState === 'FAILED') throw new Error(`ECS rollout failed: ${primary.rolloutStateReason || 'unknown reason'}`);
  await new Promise((resolve) => setTimeout(resolve, 5000));
}
throw new Error(`Timed out waiting for Sulu ${request.image_tag} deployment: ${JSON.stringify(status)}`);
